// Text of the generated files under sdk/typescript/src/generated, from the operations in sdk-ts-ops.ts.
import type { SdkOp } from './sdk-ts-ops.ts';
import { key, type Schema, tsType } from './sdk-ts-schema.ts';

/** The `ErrorCode` union: every code docs/api/errors.json lists, so `ApiError.code` can be narrowed. */
export function errorCodesFile(codes: string[]): string {
  const sorted = [...codes].sort();
  return `${HEADER}export type ErrorCode =\n${sorted.map((c) => `  | '${c}'`).join('\n')};\n`;
}

const HEADER = '// Generated by tools/gen-sdk-ts.ts from docs/api/openapi.v1.json. Do not edit.\n';
const RESERVED = new Set(['core', 'mode', 'options', 'baseUrl']);

const pascal = (parts: string[]): string =>
  parts.join(' ').replace(/(^|[^A-Za-z0-9]+)([A-Za-z0-9])/g, (_, __, c) => c.toUpperCase());
const kebab = (text: string): string => text.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`);
const className = (path: string[]): string => `${pascal(path)}Resource`;

export function schemasFile(schemas: Record<string, Schema>): string {
  const body = Object.entries(schemas)
    .sort(([a], [b]) => (a < b ? -1 : 1))
    .map(([name, schema]) => `export type ${name} = ${tsType(schema)};\n`);
  return `${HEADER}\n${body.join('\n')}`;
}

/** Every operation's body, query and success types, named `<Resource><Method>Body|Query|Result`. */
export function operationTypesFile(ops: SdkOp[], schemaNames: Set<string>): string {
  const lines: string[] = [];
  const add = (name: string, type: string, doc: string) => {
    if (schemaNames.has(name)) throw new Error(`${name} is also a schema name`);
    lines.push(`/** ${doc} */\nexport type ${name} = ${type};\n`);
  };
  for (const op of ops) {
    const what = `${op.resource.join('.')}.${op.method}`;
    if (op.body) add(`${op.typeName}Body`, op.body.type, `Request body of \`${what}\`.`);
    if (op.query) add(`${op.typeName}Query`, op.query.type, `Query of \`${what}\`.`);
    if (op.result !== 'void' && op.result !== 'Response')
      add(`${op.typeName}Result`, op.result, `Response of \`${what}\`.`);
  }
  const text = lines.join('\n').replace(/"(?:[^"\\]|\\.)*"/g, '');
  const used = [...new Set(text.match(/\b[A-Z]\w*\b/g) ?? [])]
    .filter((n) => schemaNames.has(n))
    .sort();
  const imports = used.length ? `import type { ${used.join(', ')} } from './schemas.ts';\n\n` : '';
  return `${HEADER}${imports}${lines.join('\n')}`;
}

interface Node {
  path: string[];
  ops: SdkOp[];
  children: Map<string, Node>;
}

export function resourceTree(ops: SdkOp[]): Map<string, Node> {
  const roots = new Map<string, Node>();
  for (const op of ops) {
    let level = roots;
    let node: Node | undefined;
    op.resource.forEach((segment, i) => {
      node = level.get(segment);
      if (!node) {
        node = { path: op.resource.slice(0, i + 1), ops: [], children: new Map() };
        level.set(segment, node);
      }
      level = node.children;
    });
    node?.ops.push(op);
  }
  for (const [name] of roots)
    if (RESERVED.has(name)) throw new Error(`Resource ${name} is reserved`);
  return roots;
}

function methodText(op: SdkOp): string {
  const args = op.pathParams.map((p) => `${p.name}: ${p.type}`);
  const spec = [`method: '${op.http}'`];
  const path = op.path.replace(/\{(\w+)\}/g, (_, n: string) => `\${encodeURIComponent(${n})}`);
  spec.push(op.pathParams.length ? `path: \`${path}\`` : `path: '${path}'`);
  let options = 'RequestOptions';
  if (op.body) {
    args.push(`body${op.body.required ? '' : '?'}: ${op.typeName}Body`);
    spec.push('body');
    if (op.query) options = `RequestOptions<${op.typeName}Query>`;
  } else if (op.query) {
    args.push(`query${op.query.required ? '' : '?'}: ${op.typeName}Query`);
    spec.push('query');
  }
  if (op.binary) {
    args.push('body: Blob | ArrayBuffer | Uint8Array');
    spec.push('body', `contentType: '${op.binary}'`);
  }
  if (op.idempotent) spec.push('idempotent: true');
  if (op.raw) spec.push('raw: true');
  args.push(`options?: ${options}`);
  const result =
    op.result === 'void' || op.result === 'Response' ? op.result : `${op.typeName}Result`;
  const call = op.cursor
    ? `this.core.paginate({ ${spec.join(', ')} }, '${op.cursor}', options)`
    : `this.core.request({ ${spec.join(', ')} }, options)`;
  const returns = op.cursor ? `PagePromise<${result}>` : `Promise<${result}>`;
  const doc = `${op.summary ? `${op.summary} ` : ''}\`${op.http} ${op.path}\``;
  return `  /** ${doc} */\n  ${key(op.method)}(${args.join(', ')}): ${returns} {\n    return ${call};\n  }\n`;
}

function classText(node: Node): string {
  const children = [...node.children.entries()];
  for (const [name] of children)
    if (node.ops.some((op) => op.method === name))
      throw new Error(`${node.path.join('.')} has both a method and a resource named ${name}`);
  const fields = children.map(
    ([name, child]) => `  readonly ${key(name)}: ${className(child.path)};\n`,
  );
  const inits = children.map(
    ([name, child]) => `    this.${key(name)} = new ${className(child.path)}(core);\n`,
  );
  const methods = node.ops.sort((a, b) => (a.method < b.method ? -1 : 1)).map(methodText);
  return [
    `export class ${className(node.path)} {\n`,
    '  private readonly core: Core;\n',
    ...fields,
    '  constructor(core: Core) {\n    this.core = core;\n',
    ...inits,
    '  }\n',
    ...methods.map((m) => `\n${m}`),
    '}\n',
  ].join('');
}

function* walk(node: Node): Generator<Node> {
  for (const child of node.children.values()) yield* walk(child);
  yield node;
}

/** One file per top-level resource, holding the classes of its whole subtree. */
export function resourceFiles(tree: Map<string, Node>): Map<string, string> {
  const files = new Map<string, string>();
  for (const [name, root] of tree) {
    const nodes = [...walk(root)];
    const ops = nodes.flatMap((n) => n.ops);
    const used = new Set<string>();
    for (const op of ops) {
      if (op.body) used.add(`${op.typeName}Body`);
      if (op.query) used.add(`${op.typeName}Query`);
      if (op.result !== 'void' && op.result !== 'Response') used.add(`${op.typeName}Result`);
    }
    const typeImport = used.size
      ? `import type { ${[...used].sort().join(', ')} } from '../operation-types.ts';\n`
      : '';
    const runtime = [
      'Core',
      'RequestOptions',
      ...(ops.some((o) => o.cursor) ? ['PagePromise'] : []),
    ]
      .sort()
      .join(', ');
    files.set(
      `resources/${kebab(name)}.ts`,
      `${HEADER}${typeImport}import type { ${runtime} } from '../../core.ts';\n\n${nodes.map(classText).join('\n')}`,
    );
  }
  return files;
}

export function rootFile(tree: Map<string, Node>): string {
  const entries = [...tree.entries()];
  const imports = entries.map(
    ([name, node]) => `import { ${className(node.path)} } from './resources/${kebab(name)}.ts';\n`,
  );
  const fields = entries.map(
    ([name, node]) => `  readonly ${key(name)}: ${className(node.path)};\n`,
  );
  const inits = entries.map(
    ([name, node]) => `    this.${key(name)} = new ${className(node.path)}(core);\n`,
  );
  return `${HEADER}import type { Core } from '../core.ts';\n${imports.join('')}\n/** Every resource, named as in docs/api/sdk-names.json. */\nexport class Resources {\n${fields.join('')}  constructor(core: Core) {\n${inits.join('')}  }\n}\n`;
}
